entries.css:
.grid-asymmetric { display: grid; grid-template-columns: repeat(12, 1fr); gap: var(--space-m); }
.grid-asymmetric > :nth-child(3n+1) { grid-column: span 7; }
.grid-asymmetric > :nth-child(3n+2) { grid-column: span 5; }
.grid-asymmetric > :nth-child(3n+3) { grid-column: span 12; }

.card-3d { perspective: 1000px; transform-style: preserve-3d; }
.card-3d-inner { transition: transform .15s ease-out; will-change: transform; }
// JS: rotateY(x*15deg) rotateX(-y*15deg)，鼠标离开归零

.product-card { padding: var(--space-l); border-radius: clamp(.75rem, 1.5vw, 1.5rem); display: flex; flex-direction: column; align-items: center; }
.product-card:nth-child(1) { background: #fef3e2; }
.product-card:nth-child(2) { background: #e8f4f8; }
.product-card:nth-child(3) { background: #f3e8f9; }
.product-card:nth-child(4) { background: #e8f8e9; }

.nav-link { position: relative; text-decoration: none; }
.nav-link::after { content: ''; position: absolute; bottom: -2px; left: 0; width: 100%; height: 1px; background: currentColor; transform: scaleX(0); transform-origin: bottom right; transition: transform .35s ease; }
.nav-link:hover::after { transform: scaleX(1); transform-origin: bottom left; }

.btn-slide { overflow: hidden; position: relative; }
.btn-slide span { display: block; transition: transform .4s cubic-bezier(.23,1,.32,1); }
.btn-slide::after { content: attr(data-text); position: absolute; top: 100%; left: 0; width: 100%; text-align: center; transition: transform .4s cubic-bezier(.23,1,.32,1); }
.btn-slide:hover span, .btn-slide:hover::after { transform: translateY(-100%); }

.section { padding: var(--space-3xl) var(--space-m); }
.section--dark { background: var(--color-surface-dark); color: var(--color-text-on-dark); }
.section--light { background: var(--color-surface-light); color: var(--color-text-primary); }
.section--accent { background: var(--color-brand); color: var(--color-text-on-brand); }

.hero-split { display: grid; grid-template-columns: 1fr 1fr; min-height: 100vh; align-items: center; }
.hero-split__media img { width: 100%; height: 100%; object-fit: cover; }
@media (max-width: 768px) { .hero-split { grid-template-columns: 1fr; min-height: auto; } }

.text-reveal { overflow: hidden; }
.text-reveal span { display: inline-block; transform: translateY(100%); transition: transform .8s cubic-bezier(.23,1,.32,1); }
.text-reveal.visible span { transform: translateY(0); }

/* 给 body 预留滚动条槽位，避免开关弹窗时页面横向抖一下 */
html { scrollbar-gutter: stable; }
body.is-locked { overflow: hidden; }

/* 老浏览器没有 scrollbar-gutter 时，用 JS 补等效的 padding */
const w = window.innerWidth - document.documentElement.clientWidth;
document.body.style.paddingRight = w + 'px';

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }
}

.heading-bright { color: #fff; }
.heading-muted { color: #696F81; }
